result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "expr_opt.py", "content": """"Arithmetic expression interpreter with an optimization pass.

Language
--------
Unbounded integers, variables (identifiers), integer literals, the binary
operators ``+ - * /``, unary ``-``, and parentheses.  ``/`` is **floor
division** (Python ``//``), so the language has pure integer semantics:
addition, subtraction and multiplication are exactly associative and
commutative over Z, and there is no overflow.

AST
---
* ``("num", int)``
* ``("var", name)``
* ``("bin", op, lhs, rhs)``   with op in "+-*/"
(unary minus desugars to ``("bin", "-", ("num", 0), x)``)

Public API
----------
``parse(text) -> ast``
``optimize(ast) -> ast``
``evaluate(ast, env) -> (value, ops_count)``   -- ops_count = number of
binary-operator evaluations performed by the tree walker.

Optimizations performed by ``optimize``
---------------------------------------
1. Constant folding:      BinOp(num, num) -> num
   (division guarded: a constant divisor of 0 is left untouched so the
   program still raises ZeroDivisionError at run time).

2. Identity simplification:
      x+0 -> x     0+x -> x     x-0 -> x
      x*1 -> x     1*x -> x     x/1 -> x
      x*0 -> 0     0*x -> 0     BUT only if the discarded operand contains
      no division anywhere -- otherwise the rewrite would mask a latent
      ZeroDivisionError (e.g. 0*(a/b) must keep raising when b == 0).

3. Re-association of constant chains (exact for integers):
      x+2+3 -> x+5        2*a*3 -> a*6        a-2-3 -> a+(-5)  (== a-5)
      a+2-2 -> a
   Additive (+/-) chains and multiplicative (*) chains are flattened into
   signed leaves; leaves that are integer constants are merged into one
   constant.  This is *provably* value-preserving:
     * moving a constant leaf across a variable subexpression only uses
       commutativity of + (or *) on Z, which is exact;
     * merging >= 2 constants uses associativity of + (or *) on Z, exact;
     * unbounded ints mean no overflow can invalidate the regrouping;
     * a rewrite is applied ONLY when it merges at least two constants or
       cancels a zero, i.e. only when it actually saves work.

THE DIVISION RULE -- "/" is an absolute re-association barrier
--------------------------------------------------------------
``optimize`` never moves a constant across, into, or out of a ``/``:

  * ``(a/2)/2`` stays ``(a/2)/2`` (never rewritten to ``a/4``);
  * ``(a*3)/2`` stays ``(a*3)/2`` (never rewritten to ``a*(3/2)``);
  * ``12/a/3`` stays ``12/a/3``;
  * ``(a+b)/2`` is never distributed or merged;
  * the ONLY division rewrite is full constant folding ``c1/c2 -> num``
    when both operands are literal constants and ``c2 != 0``.

Why so conservative?  Integer division is not compatible with the
regroupings that are safe for + and *.  One concrete counterexample for
the tempting rewrite ``(a*3)/2 -> a*(3/2)`` with floor division:

    a = 2:   raw  (2*3)//2 = 3        naive opt  2*(3//2) = 2   WRONG

Merging consecutive divisors, ``(a/2)/2 -> a/4``, happens to be
value-preserving for floor division with positive divisors (the nested
floor-division identity floor(floor(x/m)/n) = floor(x/(mn))), but we
still refuse it: the general family of "divide the constants out"
rewrites is unsafe (see the counterexample above), distinguishing the
safe special cases adds fragile reasoning for negligible gain, and a
future change of division semantics (e.g. trunc-toward-zero) would
silently break even the "safe" case.  Hence: division folds only when
it is a pure constant expression; everything else about a division is
left exactly where the parser put it.
"""

import re

__all__ = ["parse", "optimize", "evaluate"]


# --------------------------------------------------------------------------
# Tokenizer + recursive-descent parser
#
#   expr   := term (('+'|'-') term)*
#   term   := factor (('*'|'/') factor)*
#   factor := ('+'|'-') factor | INT | IDENT | '(' expr ')'
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"[ \t\r\n]*(?:(?P<num>\d+)|(?P<ident>[A-Za-z_]\w*)|(?P<sym>[-+*/()]))"
)


def _tokenize(text):
    tokens, pos = [], 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if m is None:
            rest = text[pos:]
            if rest.strip():
                raise SyntaxError(
                    "unexpected character %r at position %d"
                    % (rest.lstrip()[0], pos + (len(rest) - len(rest.lstrip())))
                )
            break
        pos = m.end()
        if m.group("num") is not None:
            tokens.append(("num", int(m.group("num"))))
        elif m.group("ident") is not None:
            tokens.append(("ident", m.group("ident")))
        else:
            tokens.append(("sym", m.group("sym")))
    tokens.append(("end", None))
    return tokens


class _Parser:
    def __init__(self, text):
        self.toks = _tokenize(text)
        self.i = 0

    def _peek(self):
        return self.toks[self.i]

    def _next(self):
        tok = self.toks[self.i]
        self.i += 1
        return tok

    def _expect(self, sym):
        tok = self._next()
        if tok != ("sym", sym):
            raise SyntaxError("expected %r, got %r" % (sym, tok[1]))

    def parse(self):
        node = self._expr()
        if self._peek()[0] != "end":
            raise SyntaxError("unexpected trailing token %r" % (self._peek()[1],))
        return node

    def _expr(self):
        node = self._term()
        while self._peek() in (("sym", "+"), ("sym", "-")):
            op = self._next()[1]
            node = ("bin", op, node, self._term())
        return node

    def _term(self):
        node = self._factor()
        while self._peek() in (("sym", "*"), ("sym", "/")):
            op = self._next()[1]
            node = ("bin", op, node, self._factor())
        return node

    def _factor(self):
        tok = self._next()
        if tok == ("sym", "-"):
            return ("bin", "-", ("num", 0), self._factor())
        if tok == ("sym", "+"):
            return self._factor()
        if tok == ("sym", "("):
            node = self._expr()
            self._expect(")")
            return node
        if tok[0] == "num":
            return ("num", tok[1])
        if tok[0] == "ident":
            return ("var", tok[1])
        raise SyntaxError("unexpected token %r" % (tok[1],))


def parse(text):
    """Parse an arithmetic expression string into an AST."""
    return _Parser(text).parse()


# --------------------------------------------------------------------------
# Instrumented tree-walking evaluator
# --------------------------------------------------------------------------

def evaluate(node, env):
    """Evaluate ``node`` under environment ``env``.

    Returns ``(value, ops_count)`` where ``ops_count`` is the number of
    binary-operator evaluations performed.  Raises ZeroDivisionError on
    division by zero and NameError on unbound variables.
    """
    kind = node[0]
    if kind == "num":
        return (node[1], 0)
    if kind == "var":
        try:
            return (env[node[1]], 0)
        except KeyError:
            raise NameError("undefined variable %r" % node[1])
    _, op, lhs, rhs = node
    lval, lops = evaluate(lhs, env)
    rval, rops = evaluate(rhs, env)
    if op == "+":
        val = lval + rval
    elif op == "-":
        val = lval - rval
    elif op == "*":
        val = lval * rval
    elif op == "/":
        if rval == 0:
            raise ZeroDivisionError("division by zero")
        val = lval // rval          # floor division: pure integer semantics
    else:
        raise ValueError("unknown operator %r" % op)
    return (val, lops + rops + 1)


# --------------------------------------------------------------------------
# Optimizer
# --------------------------------------------------------------------------

def _is_num(node, value=None):
    return node[0] == "num" and (value is None or node[1] == value)


def _contains_div(node):
    """True if any division occurs anywhere in ``node``."""
    if node[0] != "bin":
        return False
    if node[1] == "/":
        return True
    return _contains_div(node[2]) or _contains_div(node[3])


def _arith(op, x, y):
    if op == "+":
        return x + y
    if op == "-":
        return x - y
    if op == "*":
        return x * y
    assert y != 0            # caller guards constant /0
    return x // y


def _flatten_add(node, sign, out):
    """Collect signed leaves of an additive (+/-) chain.

    A leaf is anything that is not itself +/-.  Signs bookkeep subtraction:
    a - (b + c) contributes -b, -c, exactly as integer algebra dictates.
    """
    if node[0] == "bin" and node[1] == "+":
        _flatten_add(node[2], sign, out)
        _flatten_add(node[3], sign, out)
    elif node[0] == "bin" and node[1] == "-":
        _flatten_add(node[2], sign, out)
        _flatten_add(node[3], -sign, out)
    else:
        out.append((sign, node))


def _flatten_mul(node, out):
    """Collect factors of a multiplicative (*) chain."""
    if node[0] == "bin" and node[1] == "*":
        _flatten_mul(node[2], out)
        _flatten_mul(node[3], out)
    else:
        out.append(node)


def _build_add(var_terms, const_total):
    """Left-fold signed variable terms, append merged constant at the end."""
    acc = None
    for sign, term in var_terms:
        if acc is None:
            acc = term if sign > 0 else ("bin", "-", ("num", 0), term)
        else:
            acc = ("bin", "+" if sign > 0 else "-", acc, term)
    if acc is None:
        return ("num", const_total)
    if const_total != 0:
        acc = ("bin", "+", acc, ("num", const_total))
    return acc


def _build_mul(var_factors, const_prod):
    """Left-fold variable factors, append merged constant at the end."""
    acc = var_factors[0]
    for term in var_factors[1:]:
        acc = ("bin", "*", acc, term)
    if const_prod != 1:
        acc = ("bin", "*", acc, ("num", const_prod))
    return acc


def _optimize_pass(node):
    """One bottom-up optimization pass (children first, then this node)."""
    kind = node[0]
    if kind in ("num", "var"):
        return node

    _, op, lhs, rhs = node
    lhs = _optimize_pass(lhs)
    rhs = _optimize_pass(rhs)

    # --- 1. constant folding -------------------------------------------
    if _is_num(lhs) and _is_num(rhs):
        if op != "/" or rhs[1] != 0:          # never fold constant /0
            return ("num", _arith(op, lhs[1], rhs[1]))

    # --- 2. identities --------------------------------------------------
    if op == "+":
        if _is_num(lhs, 0):
            return rhs
        if _is_num(rhs, 0):
            return lhs
    elif op == "-":
        if _is_num(rhs, 0):
            return lhs
    elif op == "*":
        if _is_num(lhs, 0) and not _contains_div(rhs):
            return ("num", 0)                 # guard: don't mask a/b errors
        if _is_num(rhs, 0) and not _contains_div(lhs):
            return ("num", 0)
        if _is_num(lhs, 1):
            return rhs
        if _is_num(rhs, 1):
            return lhs
    elif op == "/":
        if _is_num(rhs, 1):
            return lhs
        # NOTE (division rule): no other rewrite touches '/'.

    # --- 3. re-association of constant chains ---------------------------
    if op in ("+", "-"):
        terms = []
        _flatten_add(("bin", op, lhs, rhs), 1, terms)
        num_idx = [i for i, (_, t) in enumerate(terms) if t[0] == "num"]
        if len(num_idx) >= 2:                 # >=2 constants: merge them
            const_total = sum(s * t[1] for s, t in terms if t[0] == "num")
            var_terms = [(s, t) for s, t in terms if t[0] != "num"]
            return _build_add(var_terms, const_total)
        # exactly one constant and k != 0: merging impossible, moving it
        # would save no work -- leave the chain alone (minimal churn).
        return ("bin", op, lhs, rhs)

    if op == "*":
        factors = []
        _flatten_mul(("bin", "*", lhs, rhs), factors)
        num_factors = [f for f in factors if f[0] == "num"]
        prod = 1
        for f in num_factors:
            prod *= f[1]
        var_factors = [f for f in factors if f[0] != "num"]
        if prod == 0:
            # Some constant factor is 0.  Fold to 0 only if no discarded
            # subtree could raise (same guard as the x*0 identity).
            if not any(_contains_div(f) for f in var_factors):
                return ("num", 0)
            return ("bin", "*", lhs, rhs)
        if len(num_factors) >= 2:             # >=2 constants: merge them
            return _build_mul(var_factors, prod)
        return ("bin", "*", lhs, rhs)

    return ("bin", op, lhs, rhs)


def optimize(ast):
    """Return an optimized AST (fixpoint: stable under ``optimize_pass``).

    See the module docstring for precisely which rewrites are performed
    and why they are value-preserving (in particular the division rule).
    """
    current = ast
    for _ in range(100):                      # chains shrink monotonically
        nxt = _optimize_pass(current)
        if nxt == current:
            return current
        current = nxt
    return current                            # unreachable in practice
