result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_expr_opt.py", "content": """"Tests for expr_opt: correctness of the optimizer, op-count reduction,
and proof-by-test that unsafe rewrites (especially around '/') never fire.

Run with:  pytest test_expr_opt.py -q
"""

import random

import pytest

from expr_opt import parse, optimize, evaluate

VARS = ["a", "b", "c"]


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------

def outcome(ast, env):
    """(value, ops) on success, or ('zde',)/('name',) for the two possible
    runtime errors.  Used to assert error-behavior parity."""
    try:
        value, ops = evaluate(ast, env)
    except ZeroDivisionError:
        return ("zde",)
    except NameError:
        return ("name",)
    return ("ok", value, ops)


def gen_const(rng, depth):
    """Random constant-only subexpression (the folding fodder)."""
    if depth == 0 or rng.random() < 0.4:
        return ("num", rng.randint(0, 9))
    op = rng.choice("++--**//")
    return ("bin", op, gen_const(rng, depth - 1), gen_const(rng, depth - 1))


def gen_expr(rng, depth):
    """Random expression over a,b,c with many constant subterms."""
    if depth == 0:
        if rng.random() < 0.5:
            return ("num", rng.randint(0, 9))
        return ("var", rng.choice(VARS))
    if rng.random() < 0.35:                       # sprinkle constant subtrees
        return gen_const(rng, min(depth, 3))
    op = rng.choice("++--**//")
    return ("bin", op, gen_expr(rng, depth - 1), gen_expr(rng, depth - 1))


# --------------------------------------------------------------------------
# parser / evaluator basics
# --------------------------------------------------------------------------

class TestParserEvaluator:
    def test_precedence_and_parens(self):
        assert parse("2+3*4") == ("bin", "+", ("num", 2),
                                  ("bin", "*", ("num", 3), ("num", 4)))
        assert parse("(2+3)*4") == ("bin", "*", ("bin", "+", ("num", 2),
                                                ("num", 3)), ("num", 4))

    def test_evaluate_values(self):
        assert evaluate(parse("2+3*4"), {}) == (14, 2)
        assert evaluate(parse("(2+3)*4"), {}) == (20, 2)
        assert evaluate(parse("x"), {"x": 7}) == (7, 0)
        # floor division, including negatives
        assert evaluate(parse("7/2"), {}) == (3, 1)
        assert evaluate(parse("(0-7)/2"), {}) == (-4, 2)

    def test_ops_count_counts_every_binary_op(self):
        # ((1+2)+3): two additions
        assert evaluate(parse("1+2+3"), {})[1] == 2
        # 2*3 + x*y*z: three ops
        assert evaluate(parse("2*3+x*y*z"), {"x": 1, "y": 2, "z": 3})[1] == 3
        assert evaluate(parse("42"), {})[1] == 0

    def test_runtime_errors(self):
        with pytest.raises(ZeroDivisionError):
            evaluate(parse("a/0"), {"a": 1})
        with pytest.raises(NameError):
            evaluate(parse("q+1"), {})

    def test_syntax_errors(self):
        for bad in ["2+", "(1", "1)", "2 @ 3", "*3", ""]:
            with pytest.raises(SyntaxError):
                parse(bad)


# --------------------------------------------------------------------------
# optimization: hand-proven cases
# --------------------------------------------------------------------------

class TestConstantFolding:
    def test_task_example_2_3_x(self):
        assert optimize(parse("2*3+x")) == \
            ("bin", "+", ("num", 6), ("var", "x"))

    def test_nested_folding(self):
        assert optimize(parse("(1+2)*(3+4)+a")) == \
            ("bin", "+", ("num", 21), ("var", "a"))

    def test_constant_zero_division_not_folded(self):
        # must survive to run time so the program still raises
        ast = optimize(parse("4/0"))
        assert ast == ("bin", "/", ("num", 4), ("num", 0))
        with pytest.raises(ZeroDivisionError):
            evaluate(ast, {})


class TestIdentities:
    @pytest.mark.parametrize("src", [
        "x+0", "0+x", "x-0", "x/1", "x*1", "1*x",
    ])
    def test_identity_to_x(self, src):
        assert optimize(parse(src)) == ("var", "x")

    def test_mul_zero_folds_to_zero(self):
        assert optimize(parse("x*0")) == ("num", 0)
        assert optimize(parse("0*x")) == ("num", 0)
        assert optimize(parse("(a+b*c)*0")) == ("num", 0)

    def test_mul_zero_with_division_inside_is_NOT_folded(self):
        # 0*(a/b) -> 0 would mask ZeroDivisionError when b == 0.
        # Documented rule: x*0 -> 0 only if the dropped side has no division.
        ast = optimize(parse("0*(a/b)"))
        assert ast != ("num", 0)
        with pytest.raises(ZeroDivisionError):
            evaluate(ast, {"a": 1, "b": 0})

    def test_error_parity_before_and_after_optimization(self):
        for src in ["a/0", "b/(c-c)", "0*(a/b)", "nope+1"]:
            ast = parse(src)
            opt = optimize(ast)
            env = {"a": 3, "b": 5, "c": 2}
            assert outcome(ast, env)[0] == outcome(opt, env)[0] != "ok"


class TestReassociation:
    def test_additive_chains_merge_constants(self):
        assert optimize(parse("x+2+3")) == ("bin", "+", ("var", "x"), ("num", 5))
        assert optimize(parse("2+3+x")) == ("bin", "+", ("var", "x"), ("num", 5))
        assert optimize(parse("a-2-3")) == ("bin", "+", ("var", "a"), ("num", -5))

    def test_multiplicative_chains_merge_constants(self):
        assert optimize(parse("2*a*3")) == ("bin", "*", ("var", "a"), ("num", 6))
        assert optimize(parse("a*2*b*3")) == \
            ("bin", "*", ("bin", "*", ("var", "a"), ("var", "b")), ("num", 6))

    def test_zero_cancels_in_chain(self):
        assert optimize(parse("a+2-2")) == ("var", "a")

    def test_sign_bookkeeping_across_subtraction(self):
        # a - (b - 2) = a - b + 2 : the 2 must flip sign correctly
        opt = optimize(parse("a-(b-2)-3"))
        val, _ = evaluate(opt, {"a": 10, "b": 4})
        assert val == 10 - (4 - 2) - 3


class TestDivisionIsABarrier:
    """The documented rule: '/' is never reassociated.

    Only full constant/constant division (nonzero divisor) folds.  Why the
    tempting rewrites are refused -- concrete counterexample for
    (a*3)/2 -> a*(3/2) under floor division:

        a = 2:   raw  (2*3)//2 = 3     naive rewrite  2*(3//2) = 2   WRONG

